Backend SSE endpoint that broadcasts real-time pipeline run events (story pass/fail/retry, run start/finish) to connected frontend clients.

File: ~/rorca/backend/src/lib/sse-hub.ts
```typescript
// Simple pub/sub for SSE connections
type Subscriber = (event: string, data: unknown) => void;
const subscribers = new Map<string, Set<Subscriber>>();

export function subscribe(runId: string, cb: Subscriber): () => void {
  if (!subscribers.has(runId)) subscribers.set(runId, new Set());
  subscribers.get(runId)!.add(cb);
  return () => subscribers.get(runId)!.delete(cb); // unsubscribe
}

export function broadcast(runId: string, event: string, data: unknown) {
  const subs = subscribers.get(runId);
  if (!subs) return;
  for (const cb of subs) cb(event, data);
}

export function broadcastAll(event: string, data: unknown) {
  for (const [, subs] of subscribers) {
    for (const cb of subs) cb(event, data);
  }
}
```

File: ~/rorca/backend/src/routes/pipeline.ts

GET /api/pipeline/stream?runId= (or 'all' to subscribe to all runs)
```typescript
router.get('/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.flushHeaders();

  const runId = (req.query.runId as string) || 'all';
  const unsub = subscribe(runId, (event, data) => {
    res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  });

  // Heartbeat every 15s to prevent proxy timeout
  const heartbeat = setInterval(() => res.write(':heartbeat\n\n'), 15000);

  req.on('close', () => { unsub(); clearInterval(heartbeat); });
});
```

