SSE hook: ~/rorca/src/hooks/usePipelineSSE.ts
```typescript
export function usePipelineSSE(runId: string) {
  const [events, setEvents] = useState<WalEvent[]>([]);
  useEffect(() => {
    const url = `${API_BASE}/api/pipeline/stream?runId=${runId}`;
    const es = new EventSource(url);
    es.addEventListener('wal_event', e => {
      setEvents(prev => [...prev, JSON.parse(e.data)]);
    });
    return () => es.close();
  }, [runId]);
  return events;
}
```

Deriving story state from WAL events:
- Each event has event_type: 'story_started' | 'story_passed' | 'story_failed' | 'story_retry'
- Compute story status array from the event stream
- This is the source of truth — no polling needed

